//! Event generator traits.

use crate::events::{
    Scenario,
    v1::{self, Event},
};
use crate::time::TscCount;

use crate::simulation::oscillator::FullModel;

use std::collections::HashMap;

/// An Event generator
///
/// An instance of a struct that implements this can be seen as a singular clock source.
pub trait Generator {
    /// Check when the next event will be generated by this event generator.
    ///
    /// This is used as a guarding check before calling [`Generator::generate`], and allows
    /// orchestrators of multiple generators to decide which generator will generate the *soonest* event
    /// in the current simulation.
    ///
    /// If the generator *would* generate before the `local_oscillator` is ready, currently implementations
    /// should return the earliest `TscCount` that exists within the `oscillator` input.
    fn next_event_ready(&self, oscillator: &FullModel) -> Option<TscCount>;

    /// Generate the next event for this generator.
    ///
    /// # Panics
    /// This call is allowed to panic if [`Generator::next_event_ready`] would return `None`.
    ///
    /// Callers of this trait should ensure `next_event_ready` returns a `Some` value before each
    /// invocation of [`Generator::generate`]. Furthermore, they should ensure the same `local_oscillator` is passed into
    /// [`Generator::next_event_ready`] and [`Generator::generate`] without mutations to the `local_oscillator`.
    fn generate(&mut self, oscillator: &FullModel) -> Event;
}

/// Convenience functions for types that implement [`Generator`]
pub trait GeneratorExt: Generator {
    /// Generate a full scenario from a [`FullModel`]
    ///
    /// This will take the scenario as it currently exists, and exhaust it after running.
    /// The output scenario will contains ALL of the events of this generator.
    fn create_scenario(&mut self, full_model: FullModel) -> Scenario {
        let mut events = Vec::new();
        while self.next_event_ready(&full_model).is_some() {
            events.push(self.generate(&full_model));
        }

        let scenario = v1::Scenario {
            events,
            oscillator: Some(full_model.to_oscillator()),
            metadata: HashMap::new(),
        };

        Scenario::V1(scenario)
    }
}

impl<T: Generator> GeneratorExt for T {}

#[cfg(test)]
mod test {
    use crate::events::Scenario;
    use crate::time::{EstimateDuration, Frequency, TrueDuration, TrueInstant};

    use crate::simulation::generator::GeneratorExt;
    use crate::simulation::ntp::PerfectGenerator;
    use crate::simulation::oscillator::{FullModel, Oscillator};

    use super::*;

    #[test]
    fn create_scenario() {
        let mut generator = PerfectGenerator::builder()
            .id(String::from("test"))
            .poll_period(EstimateDuration::from_secs(8))
            .build();
        let oscillator = Oscillator::create_simple()
            .clock_frequency(Frequency::from_ghz(1.0))
            .start_time(TrueInstant::from_days(364))
            .duration(TrueDuration::from_minutes(5))
            .call();

        let full_model = FullModel::calculate_from_oscillator(oscillator);

        let scenario = generator.create_scenario(full_model.clone());
        assert!(generator.next_event_ready(&full_model).is_none());
        let Scenario::V1(scenario) = scenario;

        assert_eq!(scenario.oscillator.unwrap(), full_model.to_oscillator());
        assert_eq!(scenario.events.len(), 37);
    }
}
